/* Two offset grids of thin rings: each ring touches its neighbours, and the second grid sits
   half a cell over, so the rings interlock into a lattice of lenses and four-point stars. */
.mrcresidencesbocaraton-pattern {
  --mrc-pattern-cell: 26px;
  --mrc-pattern-ring: radial-gradient(
    circle,
    transparent calc(var(--mrc-pattern-cell) / 2 - 1.25px),
    var(--mrc-pattern-line) calc(var(--mrc-pattern-cell) / 2 - 1px) calc(var(--mrc-pattern-cell) / 2 - 0.25px),
    transparent calc(var(--mrc-pattern-cell) / 2)
  );
  background-image: var(--mrc-pattern-ring), var(--mrc-pattern-ring);
  background-size: var(--mrc-pattern-cell) var(--mrc-pattern-cell);
  background-position:
    0 0,
    calc(var(--mrc-pattern-cell) / 2) calc(var(--mrc-pattern-cell) / 2);
}

.mrcresidencesbocaraton-pattern[data-tone="line"] {
  --mrc-pattern-line: var(--highlight);
}

.mrcresidencesbocaraton-pattern[data-tone="faint"] {
  --mrc-pattern-line: color-mix(in oklab, var(--primary-foreground) 22%, transparent);
}

@media (min-width: 64rem) {
  .mrcresidencesbocaraton-pattern {
    --mrc-pattern-cell: 38px;
  }
}

import { cn } from "@foundry/foundry-utils";
import "./mrcresidencesbocaraton-pattern.css";

export interface MrcresidencesbocaratonPatternProps {
  /** line colour: the theme's highlight, or a faint tint of the text on a primary band */
  tone?: "line" | "faint";
  /** sizing and position of the panel */
  className?: string;
}

export function MrcresidencesbocaratonPattern({ tone = "line", className }: MrcresidencesbocaratonPatternProps) {
  return <div aria-hidden data-tone={tone} className={cn("mrcresidencesbocaraton-pattern", className)} />;
}
